from pathlib import Path
import re,json
p=Path('public/index.html');s=p.read_text();secs=re.findall(r'<section\b.*?</section>',s)
def section(n,name,kicker,title,body,scene):
 global s
 old=secs[n-1];s=s.replace(old,f'<section class="chapter" data-name="{name}" id="chapter-{n}" aria-labelledby="s{n}"><div class="eyebrow">0{n} / {name}</div><div class="layout"><div class="copy"><div class="chapter-tool">{kicker}</div><h2 id="s{n}">{title}</h2><p class="body">{body}</p></div>{scene}</div></section>')
def panel(x):return '<div class="toolscene"><div class="schematic">'+x+'</div></div>'
s=s.replace('Start with an agent that knows nothing. Give him a place to run, a crew to build with, and knowledge he can use. RiverRoo is the story of what we can build with the RuvNet toolkit.','He has two cards and no poker strategy. We could make him play faster. Instead, we ask a better question: <strong>what would he need to learn to become a player?</strong> This is the evolution of RiverRoo—and the RuvNet tools we reached for at each step.')
s=s.replace('“Two cards. No idea.”','“What am I supposed to learn?”')
section(2,'Research the player','Ruflo / begin with the research question','Before teaching poker,<br><em>research the player.</em>','The first research brief for <strong>Ruflo</strong>: what makes a capable poker player? Not just card arithmetic—reading opponents, creating uncertainty, using position, and knowing when a strategy needs to change.<br><br>The ten areas are the project’s research framework. They become a curriculum: name each ability, define what it should do, then decide how to test it.<br><br><strong>RuOS</strong> provides the remote lab. Ruflo organises the work. The next scene turns the research brief into something we can inspect.',panel('''<div class="stamp">QUESTION → RESEARCH FRAMEWORK → TEST PLAN</div><div class="brain-question"><small>THE RESEARCH BRIEF</small>“What does a good poker player know that RiverRoo doesn’t?”</div><div class="wire"></div><div class="toolnode"><strong>Ruflo research workflow</strong><small>Break the broad goal into skill areas and bounded work.</small></div><div class="wire delayed"></div><div class="toolnode discovery-hit"><strong>A map of ten abilities</strong><small>Strategy, people, uncertainty, position, adaptation—not just hand ranking.</small></div><details class="source-detail"><summary>Where does this research story come from?</summary><p>Stuart describes the original workflow as Ruflo research into poker skills. Recovered records contain a 9:04 AM delegated scorecard-build prompt and the ten-dimension 10 AM checkpoint. We have not recovered the original completed Ruflo research report. The diagram reconstructs that workflow; it is not a transcript of a verified autonomous research run.</p></details>'''))
# Recover all ten names and actual evidence from the existing version; keep them inspectable without a wall of prose.
old=secs[2]
rows=re.findall(r'<div class="ability-row" role="row"><div role="cell" class="ability-name"><small>(.*?)</small>(.*?)<span>(.*?)</span></div><div role="cell">(.*?)</div><div role="cell">(.*?)</div></div>',old)
assert len(rows)==10
skills=[{'n':n,'name':name,'status':status,'before':before,'after':after} for n,name,status,before,after in rows]
buttons=''.join(f'<button type="button" class="skill-tile" onclick="selectSkill({i})" aria-pressed="{str(i==0).lower()}"><small>{x["n"]}</small><strong>{x["name"]}</strong><span>{x["status"]}</span></button>' for i,x in enumerate(skills))
new='''<section class="chapter" data-name="The research becomes a curriculum" id="chapter-3" aria-labelledby="s3"><div class="eyebrow">03 / The research becomes a curriculum</div><div class="chapter-tool">The original ten / a skill map, not a score invented later</div><h2 id="s3">Now “get smarter”<br><em>has a meaning.</em></h2><p class="body">These ten areas were recorded in the earlier project—not supplied by this presentation. Choose an ability to see RiverRoo’s starting point, what has changed, and what we still need to measure.</p><div class="skill-workbench"><div class="skill-grid">'''+buttons+'''</div><div class="skill-inspector" aria-live="polite"><div class="stamp" id="skillNumber">ABILITY 01 / 10</div><h3 id="skillName">Mathematics</h3><div class="inspector-label">AT THE START / RECORDED BASELINE</div><p id="skillBefore"></p><div class="inspector-arrow">↓</div><div class="inspector-label now">CURRENT EVIDENCE</div><p id="skillAfter"></p><div class="skill-boundary">Implementation progress is not a measured skill rating. No numerical ten-attribute baseline was recorded.</div></div></div><details class="source-detail curriculum-source"><summary>Show the origin of the ten areas</summary><p>A recovered RuOS audit log records a 9:04 AM EDT scorecard-build prompt containing ten capability areas. The 10 AM engineering checkpoint names these ten dimensions and reports qualitative progress. Earlier wording included “tactical bet sizing,” “tournament decisions,” and “self-correction”; the checkpoint names are retained here.</p><p>Source trail: RuOS activity log run-cd-home-ruv-poker-lab-codex-exec-skip-git-re-130434.log; “RiverRoo 10 AM engineering checkpoint,” message510db0eb-49e4-4ecd-a92d-1894abe5a38a. These establish the framework’s recorded history; the original completed Ruflo research output remains unrecovered.</p></details></section>'''
s=s.replace(old,new)
section(6,'Memory must earn its place','RuVector / connect experience to a decision','A notebook<br>is useful.<br><em>Does it teach him?</em>','Finding poker expertise gives us a foundation. Memory gives us somewhere to make useful experience available again.<br><br>In the separate <strong>RuVector</strong> reference prototype, a hand and opponent profile retrieve a relevant case. The retrieved information can change a decision.<br><br>But “I remembered it” is not the same as “I learned from it.” To prove learning, feedback must change a future decision—and a held-out test must show whether that change helps.',panel('''<div class="stamp">THREE DIFFERENT CLAIMS. THREE DIFFERENT TESTS.</div><div class="proof-gate"><span>01</span><div><strong>Did he remember?</strong><p>1,352 / 1,352 reference lookups matched.</p><b class="passed">RETRIEVAL CHECK PASSED</b></div></div><div class="proof-gate"><span>02</span><div><strong>Did he use the memory?</strong><p>Retrieved cases entered the restricted decision path. Direct and vector lookup agreed.</p><b class="passed">DECISION PATH CHECKED</b></div></div><div class="proof-gate"><span>03</span><div><strong>Did feedback make him better?</strong><p>Persistent retrieval alone does not establish learning or stronger full-game play.</p><b class="pending">FULL-GAME LEARNING NOT YET PROVEN</b></div></div><p class="diagram-note">The earlier elementary poker experiment remains in the technical appendix. Its score is not a full-poker result.</p>'''))
section(7,'Show the evolution','From the first exercise to a testable player / real progress','Less hand-waving.<br><em>More actual hands.</em>','The original exercise could not demonstrate a complete poker player. We now have a working heads-up environment with <strong>all four streets</strong>, betting and raises, chip accounting, and showdown.<br><br>The new heuristic considers sampled equity and pot odds. You can inspect its reason, replay a seed, and watch a complete hand.<br><br>That is progress in what RiverRoo can do. Whether his strategy is stronger still requires a fair before-and-after test.<br><br><a class="play-cta" href="/play/">Play a full hand. Inspect his decisions →</a>',panel('''<div class="stamp">PROGRESS WE CAN SHOW</div><div class="evolution-row"><small>THEN</small><strong>A limited exercise</strong><p>No demonstrated complete-hand strategy.</p></div><div class="wire"></div><div class="evolution-row present"><small>NOW</small><strong>A full-street prototype</strong><p>Legal actions · equity / pot odds · showdown · replay.<br>12 engine tests passed on RuOS; a browser hand reached showdown.</p></div><div class="wire future"></div><div class="evolution-row"><small>STILL TO EARN</small><strong>A stronger poker player</strong><p>Frozen baseline vs trained policy, unseen full hands, and separate tests across the ten abilities.</p></div>'''))
section(8,'The next chapter','The RuvNet learning loop / what comes next','The next upgrade<br>must <em>earn its seat.</em>','The toolkit gives us a process—not a magic intelligence switch.<br><br><strong>Next:</strong> adapt the relevant parts of rUv’s poker work; train on one set of hands; make feedback and memory available to future decisions; then test on hands the candidate has never seen.<br><br>Compare the baseline, trained policy, and trained policy with memory. Keep the upgrade only when the evidence supports it. Repeat the ten-ability tests to show where RiverRoo actually develops.<div class="links"><a href="/play/">Play the current prototype ↗</a><a href="/final-report.html">Evidence &amp; technical appendix ↗</a><a href="/RiverRoo-Presentation.zip" download>Download the story ↓</a></div>',panel('''<div class="stamp">THE NEXT BUILD / NOT CLAIMED COMPLETE</div><div class="next-loop"><div><small>01 / FOUNDATION</small><strong>Adapt rUv’s poker work</strong><span>Source research → running policy</span></div><div><small>02 / PRACTICE</small><strong>Learn from feedback</strong><span>Experience → explicit strategy update</span></div><div><small>03 / MEMORY</small><strong>Recall useful experience</strong><span>Persist → reopen → use in decisions</span></div><div><small>04 / EXAM</small><strong>Prove it on unseen hands</strong><span>Same opponents · same conditions · uncertainty</span></div></div><p class="proof">The beginning of the story: “I have no idea.”<br>The point of the tools: a path to finding out—and checking.</p>'''))
css='''
.skill-workbench{display:grid;grid-template-columns:1.25fr 1fr;gap:30px;margin:28px 0}.skill-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.skill-tile{text-align:left;min-height:100px;border:1px solid #40dfe82e;background:#06243bea;border-radius:9px;padding:15px;color:#e8f5fa;transition:background .2s,border-color .2s,transform .2s}.skill-tile:hover{transform:translateY(-2px);border-color:#40dfe8}.skill-tile[aria-pressed=true]{background:#14394b;border-color:#e9ac58;box-shadow:inset 3px 0 #e9ac58}.skill-tile small{font:9px system-ui;color:#56a1b6;display:block;margin-bottom:8px}.skill-tile strong{font:22px/1.1 Georgia;display:block}.skill-tile span{font:8px system-ui;color:#deb477;letter-spacing:.1em;display:block;margin-top:9px;text-transform:uppercase}.skill-inspector{position:sticky;top:110px;align-self:start;background:#041a2df5;border:1px solid #40dfe83b;border-radius:12px;padding:30px}.skill-inspector h3{font:42px/1.1 Georgia;color:#f1c381;margin:22px 0 30px}.inspector-label{font:9px system-ui;letter-spacing:.13em;color:#89a8b9}.inspector-label.now{color:#59dfe6}.skill-inspector p{font:17px/1.7 system-ui;color:#d1e2ec}.inspector-arrow{font:35px Georgia;color:#e9ac58;margin:20px 0}.skill-boundary{font:11px/1.7 system-ui;color:#98afc0;border-top:1px solid #40dfe82b;padding-top:18px;margin-top:25px}.curriculum-source{max-width:900px}.proof-gate{display:flex;gap:18px;padding:22px 0;border-bottom:1px solid #40dfe82b}.proof-gate>span{font:26px Georgia;color:#53899b}.proof-gate strong{font:25px Georgia;color:#e8f5fa}.proof-gate p{font-size:13px}.proof-gate b{font:9px/1.5 system-ui;letter-spacing:.1em}.passed{color:#5cdbcb}.pending{color:#e9ac58}.evolution-row{padding:20px;background:#09283c;border-radius:8px}.evolution-row small{font:9px system-ui;color:#87a6b9;letter-spacing:.15em;display:block;margin-bottom:10px}.evolution-row strong{font:27px Georgia;color:#e5f4f8}.evolution-row p{margin-bottom:0}.evolution-row.present{border:1px solid #40dfe8}.evolution-row.present small{color:#62e5e9}.next-loop{display:grid;gap:12px}.next-loop>div{border-left:2px solid #40dfe866;padding:12px 18px}.next-loop small,.next-loop span{display:block;font:10px/1.7 system-ui;color:#92b3c5}.next-loop small{color:#e9ac58;letter-spacing:.1em}.next-loop strong{font:24px Georgia;display:block;margin:7px 0;color:#e9f5fa}body[data-chapter="6"] #storyWorld,body[data-chapter="7"] #storyWorld,body[data-chapter="8"] #storyWorld{opacity:.18}@media(max-width:760px){.skill-workbench{display:block}.skill-grid{gap:8px}.skill-tile{min-height:100px;padding:12px}.skill-tile strong{font-size:19px}.skill-inspector{position:static;margin-top:16px;padding:23px}.skill-inspector h3{font-size:34px;margin:15px 0}.skill-inspector p{font-size:15px}.proof-gate strong{font-size:23px}.next-loop strong{font-size:22px}}
'''
s=s.replace('</style>',css+'</style>',1)
js='const pokerSkills='+json.dumps(skills)+';function selectSkill(n){const x=pokerSkills[n];document.querySelectorAll(".skill-tile").forEach((b,i)=>b.setAttribute("aria-pressed",String(i===n)));document.getElementById("skillNumber").textContent="ABILITY "+x.n+" / 10";document.getElementById("skillName").textContent=x.name;document.getElementById("skillBefore").textContent=x.before;document.getElementById("skillAfter").textContent=x.after;}selectSkill(0);'
s=s.replace('</script><script defer',js+'</script><script defer',1).replace('v1.3.2','v1.4.0')
p.write_text(s)
Path('.receipts/story-inline.js').write_text(re.search(r'<script>(.*?)</script>',s,re.S).group(1))
print('Evolution narrative v1.4.0: research origin, interactive curriculum, memory proof gates, observable progress, concrete next loop.')
